#!/usr/bin/env python
"""Generate cpp/include/clink/regmap_table.hpp from the Python register map,
so the C++ bus slave and the Python model share one definition."""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "python"))

from coherentlink.asic.regmap import DSP_REGMAP, Access  # noqa: E402

lines = [
    "#pragma once",
    "// Generated by scripts/gen_regmap_header.py from python/coherentlink/asic/regmap.py.",
    "// Do not edit by hand.",
    "",
    "#include <array>",
    "#include <cstdint>",
    "",
    '#include "clink/regfile.hpp"',
    "",
    "namespace clink {",
    "",
    f"inline constexpr std::array<RegisterDef, {len(DSP_REGMAP.registers)}> kDspRegisters{{{{",
]
for r in DSP_REGMAP:
    lines.append(
        f'    RegisterDef{{"{r.name}", 0x{r.addr:03X}, 0x{r.reset:08X}u, 0x{r.mask_of(Access.RW):08X}u, '
        f"0x{r.mask_of(Access.W1C):08X}u, 0x{r.mask_of(Access.WO):08X}u}},"
    )
lines += ["}};", "", "}  // namespace clink", ""]
out = ROOT / "cpp" / "include" / "clink" / "regmap_table.hpp"
out.write_text("\n".join(lines))
print(f"wrote {out.relative_to(ROOT)}")
